perado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"az_support_resolution":false,"az_support_not_central":true,"az_support_hardcoded":false,"az_support_wrong_purpose":false,"az_support_channel_not_independent":false,"az_support_inactive_or_expired":false,"az_support_bad_link":false,"az_support_display_changed":false,"az_support_availability_unverified":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"}]},"hash_paquete":"3d9cc76afba9789f21e87df5a34ed31bce4ebb4737d9b94c0a16c66585e716e3","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}},{"codigo":"S22AO-176-1","legacy_id":176,"version_nucleo":2,"relacionadas":["S22AO-176-2"],"coberturas":[{"legacy_id":176,"estado_cobertura":"PARCIAL","residual":"Se acreditó tabla física de modelos e historial, columnas de pesos, referencias, umbral y fila inicial activa; pendiente_decision=true en modelo observado. Falta reconciliar autoridad runtime y extensibilidad de criterios/variables y prueba de edición/versionado; no se declara reemplazo total.","diferencias":"Contraste físico 2026-11-26; Se acreditó tabla física de modelos e historial, columnas de pesos, referencias, umbral y fila inicial activa; pendiente_decision=true en modelo observado. Falta reconciliar autoridad runtime y extensibilidad de criterios/variables y prueba de edición/versionado; no se declara reemplazo total."}],"paquete":{"tipo":"CAMBIO","codigo":"S22AO-176-1","clave":"s22ao_legacy_176_0","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Modelo parametrizable de priorización de ofertas","descripcion":"BLOQUEAR cálculo de priorización multi oferta que no resuelva modelo activo, pesos descuento relativo/accesibilidad monto/urgencia normalizada, días y monto referencia, criterio desempate y umbral/interruptor urgencia crítica desde lf_ops.modelos_priorizacion; cambios de pesos trazables en lf_ops.modelos_priorizacion_historial. MOD_PRIOR_MVP_V1 es configuración inicial, no modelo fijo. Fórmula inicial pondera descuento relativo, accesibilidad y días de vigencia normalizados; desempate mayor descuento, oferta bajo umbral crítico al primer lugar cuando override activo. Recalibración sugerida con muestra {param:OFFERS.PRIORITY_RECALIBRATION_SAMPLE}, no forzada. Los parámetros OFFERS de pesos y referencias son valores iniciales de referencia, no segunda autoridad runtime ni sustituto de fila activa. Backend calcula, interfaz muestra orden recibido. No alterar tablas ni valores vigentes. Binding runtime pendiente; no modifica IG ni fuentes oficiales.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/176","solicitante":"Cristhian / Claude S22-AZ"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"az_model_scoring"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"az_model_not_active_config"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"az_model_weights_not_from_table"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_reference_not_from_table"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_history_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_formula_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_tiebreak_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_override_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_recalibration_forced"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_hardcoded"},"der":{"lit":true}}}},"pruebas":[{"entrada":{"az_model_scoring":true,"az_model_not_active_config":false,"az_model_weights_not_from_t