scuento relativo, accesibilidad y días de vigencia normalizados; desempate mayor descuento, oferta bajo umbral crítico al primer lugar cuando override activo. Recalibración sugerida con muestra {param:OFFERS.PRIORITY_RECALIBRATION_SAMPLE}, no forzada. Los parámetros OFFERS de pesos y referencias son valores iniciales de referencia, no segunda autoridad runtime ni sustituto de fila activa. Backend calcula, interfaz muestra orden recibido. No alterar tablas ni valores vigentes. Binding runtime pendiente; no modifica IG ni fuentes oficiales.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/176","solicitante":"Cristhian / Claude S22-AZ"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"az_model_scoring"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"az_model_not_active_config"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"az_model_weights_not_from_table"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_reference_not_from_table"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_history_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_formula_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_tiebreak_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_override_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_recalibration_forced"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"az_model_hardcoded"},"der":{"lit":true}}}},"pruebas":[{"entrada":{"az_model_scoring":true,"az_model_not_active_config":false,"az_model_weights_not_from_table":false,"az_model_reference_not_from_table":false,"az_model_history_missing":false,"az_model_formula_wrong":false,"az_model_tiebreak_wrong":false,"az_model_override_wrong":false,"az_model_recalibration_forced":false,"az_m